package demo

import kotlin.math.max

fun main() {
    val name = "Ada"       // read-only binding
    var visits = 3         // can be reassigned
    visits += 1

    // Templates accept a bare name or a full expression.
    println("$name has $visits visits, best ${max(41, 7)}")

    /* Block comments nest, unlike Java. */
    val grade = when {
        visits > 4 -> "regular"
        visits > 1 -> "returning"
        else -> "new"
    }
    println("grade: $grade")
}

