fun main() {
    val nickname: String? = null
    val city: String? = "Recife"

    // A safe call stops the chain when the receiver is null.
    println(nickname?.length)      // null
    println(city?.uppercase())     // RECIFE

    // Elvis chooses a fallback.
    val label = nickname ?: "anonymous"
    println(label)                 // anonymous

    // let receives the non-null value.
    city?.let { println("city has ${it.length} letters") } // city has 6 letters
}

fun describe(value: String?): String {
    if (value == null) return "missing"
    return "value is $value"
}

fun main() {
    val raw: String? = "  "
    val cleaned = raw?.trim()?.takeIf { it.isNotEmpty() }
    println(cleaned ?: "blank") // blank

    val forced = requireNotNull(cleaned) { "cleaned must not be null" }
    println(forced.length) // 0

    println(describe(null)) // missing
}

