tailrec fun factorial(n: Int, acc: Long): Long =
    if (n <= 1) acc else factorial(n - 1, acc * n)

fun main() {
    println(factorial(5, 1L)) // 120
}

import java.util.Locale

open class Shape(val name: String) {
    open fun area(): Double = 0.0
}

class Circle(private val radius: Double) : Shape("circle") {
    override fun area(): Double = Math.PI * radius * radius
}

interface Named {
    val label: String
    fun shout() = label.uppercase()
}

class Badge(override val label: String) : Named

fun main() {
    val circle = Circle(2.0)
    println("${circle.name}: ${"%.2f".format(Locale.ROOT, circle.area())}") // circle: 12.57
    println(Badge("new").shout()) // NEW
}

class Counter(start: Int) {
    var value: Int = start
        private set

    val isZero: Boolean
        get() = value == 0

    init {
        require(start >= 0) { "start must not be negative" }
    }

    fun increment() {
        value++
    }

    companion object {
        fun fresh(): Counter = Counter(0)
    }
}

fun main() {
    val counter = Counter.fresh()
    counter.increment()
    println(counter.value)  // 1
    println(counter.isZero) // false
}

import java.util.Locale

data class Money(val cents: Long, val currency: String) {
    init {
        require(cents >= 0) { "cents must not be negative" }
    }

    val display: String
        get() = "%.2f %s".format(Locale.ROOT, cents / 100.0, currency)
}

fun main() {
    val price = Money(1999, "BRL")
    println(price.display)      // 19.99 BRL
    println(price.component1()) // 1999
}

data class Order(val id: Int, val total: Int)

fun main() {
    val orders = listOf(Order(1, 40), Order(2, 75), Order(3, 120))

    val big = orders.filter { it.total >= 75 }
    val ids = orders.map { it.id }
    val bySize = orders.groupBy { if (it.total < 100) "small" else "large" }
    val sum = orders.sumOf { it.total }

    println(big.map { it.id }) // [2, 3]
    println(ids)               // [1, 2, 3]
    println(bySize.keys)       // [small, large]
    println(sum)               // 235
}

