fun applyTwice(value: Int, operation: (Int) -> Int): Int =
    operation(operation(value))

fun main() {
    println(applyTwice(5) { it * 2 }) // 20

    val add = { a: Int, b: Int -> a + b }
    println(add(3, 4)) // 7

    val words = listOf("pear", "fig", "banana")
    println(words.sortedBy { it.length })           // [fig, pear, banana]
    println((1..5).fold(0) { acc, n -> acc + n })   // 15
}

fun main() {
    val lengths = mutableListOf<Int>()

    val text = "  kotlin  "
        .also { println("raw: '$it'") } // raw: '  kotlin  '
        .trim()
        .let { it.uppercase() }

    val result = lengths.apply {
        add(text.length)
        add(text.count { ch -> ch == 'T' })
    }

    println(text)   // KOTLIN
    println(result) // [6, 1]
}

fun String?.orFallback(fallback: String): String =
    if (this == null || this.isBlank()) fallback else this

val String.wordCount: Int
    get() = trim().split(Regex("\\s+")).count { it.isNotEmpty() }

fun main() {
    val empty: String? = "   "
    println(empty.orFallback("none"))  // none
    println("one two three".wordCount) // 3
}

