object Registry {
    @JvmStatic
    fun start() = println("started")

    @JvmField
    val version = "2.2"
}

class Greeter {
    @JvmOverloads
    fun greet(name: String, greeting: String = "hello") = "$greeting, $name"
}

public class Main {
    public static void main(String[] args) {
        Registry.start();                              // static method
        System.out.println(Registry.version);          // static field
        System.out.println(new Greeter().greet("Ada")); // hello, Ada
    }
}

@Throws(IllegalArgumentException::class)
fun positive(text: String): Int {
    val value = text.toInt()
    require(value > 0) { "value must be positive" }
    return value
}

fun main() {
    // Java calls return platform types; choose the nullability yourself.
    val home: String? = System.getProperty("user.home")
    println(home?.length)

    println(positive("42")) // 42
}

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

class Calculator {
    fun add(a: Int, b: Int) = a + b
    fun divide(a: Int, b: Int) = a / b
}

class CalculatorTest {
    private val calculator = Calculator()

    @Test
    fun addsTwoNumbers() {
        assertEquals(7, calculator.add(3, 4))
    }

    @Test
    fun rejectsDivisionByZero() {
        assertFailsWith<ArithmeticException> {
            calculator.divide(9, 0)
        }
    }
}

